/**
 * Parser and types for `frontend/public/table/decals.json`.
 *
 * The carved decal set is generated by `tools/render/bake_decals.py` (Blender
 * 4.5.9). It restores only the retired pipeline's carve → paint → light step:
 * each record is a transparent RGBA face-plate overlay with the painted symbol,
 * the recessed lip/fillet and no face plate outside the carve. The shell keeps
 * its own lighting everywhere else.
 *
 * A decal is keyed by face + light rotation + symbol rotation:
 *  - `lightRotationDeg` is the baked rig rotation, chosen as
 *    `-screenRotationOfQuad(faceQuad)` so the light lands top-left on screen
 *    after the quad rotates the decal;
 *  - `symbolRotationDeg` is the extra in-plate symbol rotation
 *    (`faceRotationDeg - quadRotation`), 0 for every Phase 2 shell. The dora
 *    families will add 180/270 variants later.
 */
import { TILE_FACE_IDS, isTileFaceId } from './tiles';
import type { FaceSurface, TileFaceId } from './tiles';

export type DecalRotation = 0 | 90 | 180 | 270;

/** The separate light rigs: standing hand vs flat/lying tile. */
export type DecalSurface = FaceSurface;

export interface DecalStats {
  readonly width: number;
  readonly height: number;
  readonly alphaBBox: {
    readonly left: number;
    readonly top: number;
    readonly right: number;
    readonly bottom: number;
  } | null;
  readonly alphaPixels: number;
  readonly transparentFraction: number;
  readonly inkPixels: number;
  readonly redPixels: number;
  readonly cornerAlpha: readonly number[];
}

export interface DecalRecord {
  readonly face: TileFaceId;
  readonly surface: DecalSurface;
  readonly lightRotationDeg: DecalRotation;
  readonly symbolRotationDeg: DecalRotation;
  /** `decals/<face>-l<rotation>.png` (or .webp/.avif once encoded). */
  readonly textureFile: string;
  readonly width: number;
  readonly height: number;
  /** Normalized sub-rect of the decal that maps to the face plate. */
  readonly facePlateRect: readonly [number, number, number, number];
  readonly bytes: number;
  readonly sha256: { readonly decodedRgba: string };
  readonly measured: DecalStats;
}

export interface DecalsManifest {
  readonly version: number;
  readonly generatedBy: string;
  readonly raster: {
    readonly width: number;
    readonly height: number;
    readonly scale: number;
    readonly format: string;
  };
  readonly surfaces: readonly DecalSurface[];
  readonly surfaceRotations: Readonly<Record<string, readonly DecalRotation[]>>;
  readonly rotations: readonly DecalRotation[];
  readonly symbolRotations: readonly DecalRotation[];
  readonly budgetBytes: number;
  readonly decals: Readonly<Record<string, DecalRecord>>;
}

export function decalKey(
  face: TileFaceId,
  surface: DecalSurface,
  lightRotationDeg: DecalRotation,
  symbolRotationDeg: DecalRotation,
): string {
  return `${face}:${surface}:l${lightRotationDeg}:s${symbolRotationDeg}`;
}

export function decalFor(
  manifest: DecalsManifest | null | undefined,
  face: TileFaceId,
  surface: DecalSurface,
  lightRotationDeg: DecalRotation,
  symbolRotationDeg: DecalRotation,
): DecalRecord | null {
  if (!manifest) return null;
  return manifest.decals[decalKey(face, surface, lightRotationDeg, symbolRotationDeg)] ?? null;
}

function fail(message: string): never {
  throw new Error(`decals.json: ${message}`);
}

function finite(value: unknown, field: string): number {
  if (typeof value !== 'number' || !Number.isFinite(value)) fail(`${field} must be a finite number`);
  return value;
}

function positive(value: unknown, field: string): number {
  const number = finite(value, field);
  if (number <= 0) fail(`${field} must be positive`);
  return number;
}

function rotation(value: unknown, field: string): DecalRotation {
  if (value !== 0 && value !== 90 && value !== 180 && value !== 270) {
    fail(`${field} must be 0, 90, 180 or 270`);
  }
  return value;
}

function parseStats(id: string, raw: unknown): DecalStats {
  if (typeof raw !== 'object' || raw === null) fail(`${id}.measured must be an object`);
  const m = raw as Record<string, unknown>;
  const bboxRaw = m.alphaBBox;
  let alphaBBox: DecalStats['alphaBBox'] = null;
  if (bboxRaw !== null && bboxRaw !== undefined) {
    if (typeof bboxRaw !== 'object') fail(`${id}.measured.alphaBBox must be an object or null`);
    const b = bboxRaw as Record<string, unknown>;
    alphaBBox = {
      left: finite(b.left, `${id}.measured.alphaBBox.left`),
      top: finite(b.top, `${id}.measured.alphaBBox.top`),
      right: finite(b.right, `${id}.measured.alphaBBox.right`),
      bottom: finite(b.bottom, `${id}.measured.alphaBBox.bottom`),
    };
  }
  const corners = m.cornerAlpha;
  if (!Array.isArray(corners)) fail(`${id}.measured.cornerAlpha must be an array`);
  return {
    width: positive(m.width, `${id}.measured.width`),
    height: positive(m.height, `${id}.measured.height`),
    alphaBBox,
    alphaPixels: finite(m.alphaPixels, `${id}.measured.alphaPixels`),
    transparentFraction: finite(m.transparentFraction, `${id}.measured.transparentFraction`),
    inkPixels: finite(m.inkPixels, `${id}.measured.inkPixels`),
    redPixels: finite(m.redPixels, `${id}.measured.redPixels`),
    cornerAlpha: corners.map((value, index) => finite(value, `${id}.measured.cornerAlpha[${index}]`)),
  };
}

function parseDecal(key: string, raw: unknown): DecalRecord {
  if (typeof raw !== 'object' || raw === null) fail(`${key} must be an object`);
  const record = raw as Record<string, unknown>;
  const face = record.face;
  if (!isTileFaceId(face)) fail(`${key}.face is not a tile face`);
  const surface = record.surface;
  if (surface !== 'upright' && surface !== 'lying') {
    fail(`${key}.surface must be upright or lying`);
  }
  const light = rotation(record.lightRotationDeg, `${key}.lightRotationDeg`);
  const symbol = rotation(record.symbolRotationDeg, `${key}.symbolRotationDeg`);
  if (decalKey(face, surface, light, symbol) !== key) {
    fail(`key ${key} does not match its face/surface/rotations`);
  }
  const textureFile = record.textureFile;
  if (typeof textureFile !== 'string' || !textureFile) fail(`${key}.textureFile must be a path`);
  const rect = record.facePlateRect;
  if (
    !Array.isArray(rect) ||
    rect.length !== 4 ||
    rect.some((value) => typeof value !== 'number' || !Number.isFinite(value))
  ) {
    fail(`${key}.facePlateRect must be [x0, y0, x1, y1]`);
  }
  if (rect.some((value) => value < 0 || value > 1)) {
    fail(`${key}.facePlateRect must be normalized to 0..1`);
  }
  const sha = record.sha256;
  if (typeof sha !== 'object' || sha === null) fail(`${key}.sha256 must be an object`);
  const decoded = (sha as Record<string, unknown>).decodedRgba;
  if (typeof decoded !== 'string' || decoded.length < 16) {
    fail(`${key}.sha256.decodedRgba must be a hash`);
  }
  return {
    face,
    surface,
    lightRotationDeg: light,
    symbolRotationDeg: symbol,
    textureFile,
    width: positive(record.width, `${key}.width`),
    height: positive(record.height, `${key}.height`),
    facePlateRect: [rect[0], rect[1], rect[2], rect[3]],
    bytes: positive(record.bytes, `${key}.bytes`),
    sha256: { decodedRgba: decoded },
    measured: parseStats(key, record.measured),
  };
}

/** Parse and validate a decoded `decals.json`. */
export function parseDecalsManifest(raw: unknown): DecalsManifest {
  if (typeof raw !== 'object' || raw === null) fail('document must be an object');
  const doc = raw as Record<string, unknown>;
  if (doc.version !== 1) fail(`version must be 1, got ${String(doc.version)}`);
  if (typeof doc.raster !== 'object' || doc.raster === null) fail('raster must be an object');
  if (typeof doc.decals !== 'object' || doc.decals === null) fail('decals must be an object');
  const raster = doc.raster as Record<string, unknown>;
  const budget = doc.budget as Record<string, unknown> | undefined;
  if (!budget || typeof budget.bytes !== 'number') fail('budget.bytes must be a number');
  const surfacesRaw = doc.surfaces;
  if (!Array.isArray(surfacesRaw)) fail('surfaces must be an array');
  const surfaces = surfacesRaw.map((value, index) => {
    if (value !== 'upright' && value !== 'lying') {
      fail(`surfaces[${index}] must be upright or lying`);
    }
    return value;
  });
  const rotationsRaw = doc.rotations;
  if (!Array.isArray(rotationsRaw)) fail('rotations must be an array');
  const rotations = rotationsRaw.map((value, index) => rotation(value, `rotations[${index}]`));
  const surfaceRotationsRaw = doc.surfaceRotations;
  const surfaceRotations: Record<string, DecalRotation[]> = {};
  if (surfaceRotationsRaw !== undefined) {
    if (typeof surfaceRotationsRaw !== 'object' || surfaceRotationsRaw === null) {
      fail('surfaceRotations must be an object');
    }
    for (const [surface, values] of Object.entries(
      surfaceRotationsRaw as Record<string, unknown>,
    )) {
      if (!Array.isArray(values)) fail(`surfaceRotations.${surface} must be an array`);
      surfaceRotations[surface] = values.map((value, index) =>
        rotation(value, `surfaceRotations.${surface}[${index}]`),
      );
    }
  } else {
    for (const surface of surfaces) surfaceRotations[surface] = rotations;
  }
  const symbolRotationsRaw = doc.symbolRotations;
  if (!Array.isArray(symbolRotationsRaw)) fail('symbolRotations must be an array');
  const symbolRotations = symbolRotationsRaw.map((value, index) =>
    rotation(value, `symbolRotations[${index}]`),
  );
  const decalsRaw = doc.decals as Record<string, unknown>;
  const decals: Record<string, DecalRecord> = {};
  for (const [key, value] of Object.entries(decalsRaw)) {
    decals[key] = parseDecal(key, value);
  }
  if (Object.keys(decals).length === 0) fail('decals must not be empty');
  return {
    version: 1,
    generatedBy: typeof doc.generatedBy === 'string' ? doc.generatedBy : '',
    raster: {
      width: positive(raster.width, 'raster.width'),
      height: positive(raster.height, 'raster.height'),
      scale: positive(raster.scale, 'raster.scale'),
      format: typeof raster.format === 'string' ? raster.format : '',
    },
    surfaces,
    surfaceRotations,
    rotations,
    symbolRotations,
    budgetBytes: finite(budget.bytes, 'budget.bytes'),
    decals,
  };
}

/** True when the manifest covers every face id in the catalogue. */
export function coversAllFaces(manifest: DecalsManifest): boolean {
  const faces = new Set(Object.values(manifest.decals).map((record) => record.face));
  return TILE_FACE_IDS.every((face) => faces.has(face));
}
